<?php

namespace Database\Seeders;

use App\Models\Industry;
use Illuminate\Database\Seeder;

class IndustryContentSeeder extends Seeder
{
    public function run(): void
    {
        $profiles = $this->profiles();

        foreach (Industry::query()->select(['id', 'slug', 'name', 'short_description'])->lazyById() as $industry) {
            $profile = $profiles[$industry->slug] ?? $this->genericProfile($industry->name, $industry->short_description);

            $industry->update([
                'short_description' => $profile['short_description'],
                'seo_title' => $profile['seo_title'],
                'seo_description' => $profile['seo_description'],
                'seo_keywords' => $profile['seo_keywords'],
                'content' => $this->buildContent($profile),
            ]);
        }
    }

