    /**
     * @param  array<string, mixed>  $profile
     * @return array<string, mixed>
     */
    private function buildContent(array $profile): array
    {
        return [
            'hero' => [
                'eyebrow' => $profile['eyebrow'],
                'heading' => $profile['heading'],
                'highlight' => $profile['highlight'],
                'intro' => $profile['intro'],
                'cta_primary_label' => 'Talk to an Expert',
                'cta_secondary_label' => 'Explore Solutions',
                'features' => $this->labelItems($profile['features']),
                'badges' => $this->labelItems($profile['badges']),
            ],
            'trust' => ['enabled' => true],
            'challenges' => [
                'enabled' => true,
                'eyebrow' => 'CHALLENGES',
                'heading' => $profile['challenge_heading'],
                'subtitle' => $profile['challenge_intro'],
                'items' => $profile['challenges'],
            ],
            'solutions' => [
                'enabled' => true,
                'eyebrow' => 'HOW WE HELP',
                'heading' => $profile['solution_heading'],
                'cards' => $this->iconItems($profile['solutions']),
            ],
            'stats' => [
                'enabled' => true,
                'subtitle' => 'WHAT BETTER LOOKS LIKE',
                'heading' => 'Built for More Confident Operations',
                'items' => $this->iconItems($profile['stats']),
            ],
            'case_studies' => [
                'enabled' => true,
                'subtitle' => 'SUCCESS STORIES',
                'heading' => 'Real Results. Real Impact.',
            ],
            'solutions_grid' => [
                'enabled' => true,
                'subtitle' => 'WHAT WE OFFER',
                'heading' => 'Solutions We Offer',
                'items' => $this->labelItems($profile['grid']),
            ],
            'faq' => [
                'enabled' => true,
                'subtitle' => 'FAQS',
                'heading' => 'Frequently Asked Questions',
                'items' => $profile['faqs'],
                'cta_heading' => $profile['faq_cta_heading'],
                'cta_text' => $profile['faq_cta_text'],
                'cta_label' => 'Get Started Today',
            ],
            'cta_band' => [
                'enabled' => true,
                'heading' => $profile['cta_heading'],
                'subtitle' => $profile['cta_subtitle'],
                'button_primary_label' => 'Talk to an Expert',
                'button_secondary_label' => 'Request a Consultation',
            ],
        ];
    }

    /**
     * @param  array<int, string>  $labels
     * @return array<int, array{icon: string, label: string}>
     */
    private function labelItems(array $labels): array
    {
        return array_map(
            fn (string $label): array => ['icon' => '', 'label' => $label],
            $labels,
        );
    }

    /**
     * @param  array<int, array<string, string>>  $items
     * @return array<int, array<string, string>>
     */
    private function iconItems(array $items): array
    {
        return array_map(
            fn (array $item): array => ['icon' => '', ...$item],
            $items,
        );
    }

